ops:
  // 只匯入正式的督導／查核紀錄表：委員紀錄表、評分表等不匯入
  const title = it.rec ? it.rec.title : '';
  if(/委員紀錄|評分表/.test(title+' '+it.name)){ it.formal=false; it.conf='非正式'; it.note='委員紀錄表或評分表，不是正式紀錄表'; it.cand=[]; it.caseId=''; return; }
  it.formal = !!it.rec && /(督導|查核)紀錄/.test(title);
  if(!it.formal && it.caseId){ it.conf='待確認'; it.note=(it.note?it.note+'；':'')+'標題不是「督導／查核紀錄」'+(title?'（'+title.slice(0,30)+'）':'')+'，請確認是否為正式紀錄表'; }
/** 同一案件有多份時優先順序：正式紀錄且可解析 > Word/ODT > PDF */
const bRank = it => (it.formal?100:0) + (it.rec?10:0) + ({odt:3,docx:3,doc:2,pdf:1}[it.ext]||0);
  const used={}, best={};
  B.items.forEach(it=>{ if(it.caseId && !it.done && (!best[it.caseId] || bRank(it)>bRank(best[it.caseId]))) best[it.caseId]=it; });
    if(best[it.caseId] && best[it.caseId]!==it) it.warn='同一案件已有較適合的檔案（'+best[it.caseId].name.slice(0,30)+'）';
    if(it.done==null && it.check==null) it.check = it.conf==='確定' && it.formal!==false && !it.warn;
  $('bInfo').textContent = n ? `共 ${n} 份｜自動確定 ${ok}｜待確認 ${B.items.filter(x=>x.conf==='待確認').length}｜非正式 ${B.items.filter(x=>x.conf==='非正式').length}｜找不到 ${B.items.filter(x=>x.conf==='找不到').length}｜已勾選 ${sel}` : '';
      `<span class="badge ${it.conf==='確定'?'ok':it.conf==='待確認'?'warn':it.conf==='非正式'?'':'err'}">${it.conf||''}</span>`;
